        {
          "proposicao": "O trabalho adota a planta de processamento de óleo e gás de um FPSO como volume de controle para analisar efeitos de modos de operação, vazão de gás exportado e composição do petróleo, indicando que o desempenho global depende dessas variáveis de entrada e das restrições da planta.",
          "trechos": [
            "E95d226bce65482d2:0:700",
            "E95d226bce65482d2:700:1398",
            "E95d226bce65482d2:1398:2090"
          ],
          "condicoes": [
            "análise baseada em modelagem e cenários simulados",
            "aplicação a FPSO no pré-sal",
            "parâmetros avaliados por critérios exergéticos"
          ],
          "limites": [
            "o trecho não detalha equipamentos específicos como trocadores, bombas ou vasos",
